// Exact synthetic audit microbenchmark. No GPU/physical claims.
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <limits>
#include <numeric>
#include <string>
#include <utility>
#include <vector>
using I=__int128_t;using Clock=std::chrono::steady_clock;
volatile uint64_t checksum=0;
struct Rect{std::vector<int64_t> l,u;};
struct Plan{int id,sid,n,expect;std::vector<int64_t> pos;std::vector<std::pair<int,int>> edges,pairs;std::vector<uint8_t> R;std::array<Rect,8> rect;std::vector<std::pair<int,int>> queries,survivors;bool cheap=false,exact=false;int64_t span=0;};
struct Stratum{int id,reps;std::vector<int> ids;};
struct Schedule{int block,sid;std::array<int,4> routes;std::array<int,3> prep;};
[[noreturn]]void fail(const std::string&s){std::cerr<<s<<"\n";std::exit(2);}void require(bool b,const std::string&s){if(!b)fail(s);}
void close(Plan&p){int n=p.n;p.R.assign(n*n,0);for(auto [a,b]:p.edges)p.R[a*n+b]=1;for(int k=0;k<n;k++)for(int i=0;i<n;i++)if(p.R[i*n+k])for(int j=0;j<n;j++)p.R[i*n+j]|=p.R[k*n+j];p.pairs.clear();for(int i=0;i<n;i++){require(!p.R[i*n+i],"cyclic ranking");for(int j=0;j<n;j++)if(p.R[i*n+j])p.pairs.push_back({i,j});}p.span=p.pos.back()-p.pos.front()+1;}
bool cheap_flag(const Plan&p){bool up=true,down=true;int source=-1,target=-1;bool common_source=true,common_target=true;for(auto[a,b]:p.pairs){up&=p.pos[a]<p.pos[b];down&=p.pos[a]>p.pos[b];if(source<0)source=a;else common_source&=source==a;if(target<0)target=b;else common_target&=target==b;}return p.n<4||up||down||common_source||common_target;}
bool quartet(const Plan&p){int n=p.n;auto ok=[&](int a,int b,int c,int d){auto x=std::llabs(p.pos[a]-p.pos[c])+std::llabs(p.pos[b]-p.pos[d]);auto y=std::llabs(p.pos[a]-p.pos[d])+std::llabs(p.pos[b]-p.pos[c]);bool u=p.R[a*n+c]&&p.R[b*n+d],v=p.R[a*n+d]&&p.R[b*n+c];return !((u||v)&&std::min(u?x:INT64_MAX,v?y:INT64_MAX)>std::min(x,y));};for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)for(int c=b+1;c<n;c++)for(int d=c+1;d<n;d++){if(!ok(a,b,c,d)||!ok(a,c,b,d)||!ok(a,d,b,c)||!ok(b,c,a,d)||!ok(b,d,a,c)||!ok(c,d,a,b))return false;}return true;}
struct Scratch{std::vector<I>w,h,floyd;std::vector<int>pred;};
void graph(const Plan&p,const Rect&r,int delta,Scratch&s){int n=p.n;s.w.resize(n*n);for(int a=0;a<n;a++)for(int b=0;b<n;b++){I w=a==b?0:I(r.u[b])-r.l[a]+I(delta)*std::llabs(p.pos[a]-p.pos[b]);if(p.R[b*n+a]&&w>0)w=0;s.w[a*n+b]=w;}}
bool bf(const Plan&p,const Rect&r,int delta,Scratch&s,bool certificate){int n=p.n;graph(p,r,delta,s);s.h.assign(n,0);s.pred.assign(n,-1);int changed=-1;for(int turn=0;turn<n;turn++){changed=-1;for(int a=0;a<n;a++)for(int b=0;b<n;b++)if(s.h[b]>s.h[a]+s.w[a*n+b]){s.h[b]=s.h[a]+s.w[a*n+b];s.pred[b]=a;changed=b;}if(changed<0){if(certificate)for(int a=0;a<n;a++)for(int b=0;b<n;b++)require(s.h[b]<=s.h[a]+s.w[a*n+b],"bad feasible potential");return true;}}if(certificate){int v=changed;for(int i=0;i<n;i++){require(v>=0,"missing pred");v=s.pred[v];}int start=v,count=0;I weight=0;do{int prev=s.pred[v];require(prev>=0,"missing cycle pred");weight+=s.w[prev*n+v];v=prev;require(++count<=n,"bad cycle extraction");}while(v!=start);require(weight<0,"nonnegative reject certificate");}return false;}
bool floyd(const Plan&p,const Rect&r,int delta,Scratch&s){int n=p.n;graph(p,r,delta,s);s.floyd=s.w;for(int k=0;k<n;k++){for(int i=0;i<n;i++)for(int j=0;j<n;j++){I v=s.floyd[i*n+k]+s.floyd[k*n+j];if(v<s.floyd[i*n+j])s.floyd[i*n+j]=v;}for(int i=0;i<n;i++)if(s.floyd[i*n+i]<0)return false;}return true;}
// route codes: 0direct;1beta;2cheap+span;3quartet union+span.
// output path: 0graph,1beta reject,2cheap exact,3span,4quartet-only exact.
bool query(const Plan&p,const Rect&r,int delta,int route,Scratch&s,int*path=nullptr){if(path)*path=0;if(route){bool beta_reject=false,span_admit=true;bool exact_route=route>=2&&(p.cheap||(route==3&&p.exact));bool need_span=route>=2&&(!exact_route||path);I cap=std::max<int64_t>(1,p.span-2);for(auto[a,b]:p.pairs){I deficit=I(r.l[a])-r.u[b];I allowed=I(delta)*std::llabs(p.pos[a]-p.pos[b]);if(deficit>allowed){beta_reject=true;break;}if(need_span&&cap*deficit>allowed)span_admit=false;}if(beta_reject){if(path)*path=1;return false;}if(exact_route&&!path)return true;if(route>=2){if(p.cheap){if(path)*path=2;return true;}if(span_admit){if(path)*path=3;return true;}if(route==3&&p.exact){if(path)*path=4;return true;}}}return bf(p,r,delta,s,false);}
int main(int argc,char**argv){require(argc>=2,"mode required: validate|time");bool timing=std::string(argv[1])=="time";std::ifstream in("inputs.txt");require(bool(in),"inputs missing");int np,ns;in>>np>>ns;std::vector<Plan>plans(np);for(auto&p:plans){int ne;in>>p.id>>p.sid>>p.n>>ne>>p.expect;p.pos.resize(p.n);for(auto&x:p.pos)in>>x;for(int e=0;e<ne;e++){int a,b;in>>a>>b;p.edges.push_back({a,b});}for(auto&r:p.rect){r.l.resize(p.n);r.u.resize(p.n);for(auto&x:r.l)in>>x;for(auto&x:r.u)in>>x;}for(int k=0;k<48;k++){int ri,d;in>>ri>>d;p.queries.push_back({ri,d});}close(p);p.cheap=cheap_flag(p);p.exact=p.cheap||quartet(p);require(p.exact==bool(p.expect),"Python/native quartet mismatch");}std::vector<Stratum>strata(ns);for(auto&s:strata){int ni;in>>s.id>>s.reps>>ni;s.ids.resize(ni);for(auto&x:s.ids)in>>x;}require(bool(in),"input parse failure");std::ifstream si("schedule.txt");int nk;si>>nk;std::vector<Schedule>sched(nk);for(auto&s:sched){si>>s.block>>s.sid;for(auto&x:s.routes)si>>x;for(auto&x:s.prep)si>>x;}require(bool(si),"schedule failure");Scratch scratch;
 if(!timing){std::ofstream out("validation.csv");out<<"plan,rectangle,delta,decision,cheap_exact,quartet_exact,beta_path,cheap_path,quartet_path\n";uint64_t count=0;for(auto&p:plans){for(auto[ri,d]:p.queries){bool direct=bf(p,p.rect[ri],d,scratch,true);require(floyd(p,p.rect[ri],d,scratch)==direct,"Floyd mismatch");std::array<int,3>paths{};for(int route=1;route<4;route++){require(query(p,p.rect[ri],d,route,scratch,&paths[route-1])==direct,"route mismatch");require(query(p,p.rect[ri],d,route,scratch)==direct,"optimized timed route mismatch");}out<<p.id<<','<<ri<<','<<d<<','<<direct<<','<<p.cheap<<','<<p.exact;for(auto v:paths)out<<','<<v;out<<'\n';count++;}if((p.id+1)%100==0)std::cout<<"validated_plans "<<p.id+1<<std::endl;}std::cout<<"PASS_ALL_EXACT_ROUTES_FLOYD_AND_BF_CERTIFICATES queries="<<count<<std::endl;return 0;}
 for(auto&p:plans)for(auto[ri,d]:p.queries){bool reject=false;for(auto[a,b]:p.pairs)if(I(p.rect[ri].l[a])-p.rect[ri].u[b]>I(d)*std::llabs(p.pos[a]-p.pos[b])){reject=true;break;}if(!reject)p.survivors.push_back({ri,d});}
 std::ofstream qt("query_times.csv"),pt("preprocess_times.csv");qt<<"block,stratum,stream,order_position,route,repeats,queries_per_repeat,elapsed_ns,checksum\n";pt<<"block,stratum,order_position,stage,repeats,plans_per_repeat,elapsed_ns,checksum\n";
 // Single complete untimed warmup for every route and stage on the actual data.
 for(auto&s:strata){for(int route=0;route<4;route++)for(int id:s.ids){auto&p=plans[id];for(auto[ri,d]:p.queries)checksum+=query(p,p.rect[ri],d,route,scratch);}for(int id:s.ids){Plan p=plans[id];close(p);checksum+=p.pairs.size();checksum+=cheap_flag(p);checksum+=p.cheap||quartet(p);}}
 for(auto&sch:sched){auto&s=strata[sch.sid];for(int oi=0;oi<3;oi++){int stage=sch.prep[oi];int repetitions=stage==1?1000:20;uint64_t sum=0;auto start=Clock::now();for(int rep=0;rep<repetitions;rep++)for(int id:s.ids){asm volatile("" : : "g"(&plans[id]) : "memory");if(stage==0){Plan p;p.n=plans[id].n;p.pos=plans[id].pos;p.edges=plans[id].edges;close(p);sum+=p.pairs.size();}else if(stage==1)sum+=cheap_flag(plans[id]);else sum+=plans[id].cheap||quartet(plans[id]);}auto end=Clock::now();checksum+=sum;auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count();pt<<sch.block<<','<<s.id<<','<<oi<<','<<stage<<','<<repetitions<<','<<s.ids.size()<<','<<ns<<','<<sum<<'\n';}
 for(int so=0;so<2;so++){int stream=(so+sch.block+sch.sid)%2;size_t nq=0;for(int id:s.ids)nq+=(stream?plans[id].survivors:plans[id].queries).size();for(int oi=0;oi<4;oi++){int route=sch.routes[oi];uint64_t sum=0;auto start=Clock::now();for(int rep=0;rep<s.reps;rep++)for(int id:s.ids){auto&p=plans[id];for(auto[ri,d]:(stream?p.survivors:p.queries))sum+=query(p,p.rect[ri],d,route,scratch);}auto end=Clock::now();checksum+=sum;auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count();qt<<sch.block<<','<<s.id<<','<<stream<<','<<oi<<','<<route<<','<<s.reps<<','<<nq<<','<<ns<<','<<sum<<'\n';}}qt.flush();pt.flush();if(sch.sid==0)std::cout<<"completed block="<<sch.block<<" all720 stratum"<<std::endl;}
 std::cout<<"TIMING_COMPLETE checksum="<<checksum<<" sizeof_signed128="<<sizeof(I)<<std::endl;
}
